const ELEMENT_PROP_KEYS = new Set(["theme","label","value","weeks","fontWeight","radius","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "renders this year",
  value: 12480,
  weeks: 52,
  fontWeight: 400,
  radius: 0.26,
  accent: "#3B5BFD",
  fontFamily: "Geist",
